const { getActions, getState } = options;

const propsToShow = window.relationshipsGrid.getPropsForColumnDialog();
const params = {
	aras,
	propsToShow,
	title: aras.getResource('', 'showcolumndlg.title'),
	dialogHeight: 500,
	dialogWidth: 350,
	resizable: true,
	content: 'SitePreference/showColumnDialog.html'
};

const win = aras.getMostTopWindowWithAras();
const dialog = win.ArasModules.Dialog;
const columnsToDisplay = await dialog.show('iframe', params).promise;

if (!columnsToDisplay) {
	return;
}

const grid = getState().grid;
const order = [...grid.order];
const widths = new Map();
const columnsToInsert = propsToShow.filter((propertyInfo) =>
	columnsToDisplay.includes(propertyInfo.label)
);
columnsToInsert.forEach((column) => {
	const columnName = column.name + column.type;
	if (column.colNumber >= order.length) {
		order.push(columnName);
	} else {
		order.splice(column.colNumber, 0, columnName);
	}
	widths.set(columnName, column.width);
});

getActions().updateLayoutData({
	grid: { order, widths }
});
